# Build, dedupe and split an SFT dataset (chat-format JSONL). Standard library only.
import hashlib
import json
import random
import re
from collections import defaultdict

SYSTEM = "You are a support assistant. Answer in JSON with keys category and reply."


def normalise(text: str) -> str:
    return re.sub(r"\s+", " ", text.strip().lower())


def fingerprint(text: str) -> str:
    return hashlib.sha256(normalise(text).encode()).hexdigest()


def shingles(text: str, k: int = 5) -> set[str]:
    words = normalise(text).split()
    return {" ".join(words[i : i + k]) for i in range(max(1, len(words) - k + 1))}


def jaccard(a: set[str], b: set[str]) -> float:
    return len(a & b) / max(1, len(a | b))


def to_chat(row: dict) -> dict:
    return {
        "messages": [
            {"role": "system", "content": SYSTEM},
            {"role": "user", "content": row["input"]},
            {"role": "assistant", "content": json.dumps({"category": row["category"], "reply": row["reply"]})},
        ],
        "group": row["customer_id"],  # split by customer so near-identical threads never straddle train and test
    }


def dedupe(rows: list[dict], threshold: float = 0.8) -> list[dict]:
    seen: set[str] = set()
    kept: list[tuple[dict, set[str]]] = []
    for row in rows:
        fp = fingerprint(row["input"])
        if fp in seen:
            continue
        sh = shingles(row["input"])
        if any(jaccard(sh, other) >= threshold for _, other in kept):  # O(n^2): use MinHash/LSH beyond ~50k rows
            continue
        seen.add(fp)
        kept.append((row, sh))
    return [r for r, _ in kept]


def split_by_group(rows: list[dict], seed: int = 7) -> dict[str, list[dict]]:
    groups: dict[str, list[dict]] = defaultdict(list)
    for r in rows:
        groups[r["group"]].append(r)
    keys = sorted(groups)
    random.Random(seed).shuffle(keys)
    n = len(keys)
    cut_train, cut_val = int(n * 0.8), int(n * 0.9)
    out = {"train": [], "validation": [], "test": []}
    for i, key in enumerate(keys):
        bucket = "train" if i < cut_train else "validation" if i < cut_val else "test"
        out[bucket].extend(groups[key])
    return out


if __name__ == "__main__":
    raw = [json.loads(line) for line in open("tickets.jsonl")]
    good = [r for r in raw if 20 <= len(r["reply"]) <= 1200 and r["category"]]  # cheap quality gate
    chat = [to_chat(r) for r in dedupe(good)]
    for name, part in split_by_group(chat).items():
        with open(f"sft_{name}.jsonl", "w") as f:
            for r in part:
                f.write(json.dumps({"messages": r["messages"]}) + "\n")
        print(name, len(part))
